          "question": "1. 省略主语",
          "overview": "日语中，依据前后文能够理解其内容的句子的主语经常省略（初级第1课）；而主语内容多、用单个词语无法表达时，常常使用概括性、代表性的词语或表达方式。如本课中将王风前面所说的内容用“以上”一词来概括。“以上”是指到这里为止说过的内容。此外，还使用“これ”“それ”等指示词。",
