          "question": "2. ～抜きで",
          "overview": "“名词＋抜き”表示平常总伴随的东西不在一起了。动词“抜く”表示去除的意思，名词化后变成“抜き”。“お世辞抜きで”是指不说应酬话，表示出自真心。此外，还常常使用“～は抜きにして”的表达方式，意思与“～抜きで”相同。",
