          "question": "4. 確かに～でも～",
          "overview": "自己也认同对方所说的内容时，使用“確かに”，由二类形容词“確か”后续“に”构成。“確かに”既可以单独使用，也常常用于修饰动词或者接句子，如“確かに，そのとおりです（确实如此）”（中级第8课会话）。另外，在接受对方意见的同时提出不同看法，可以使用“でも”“が”“しかし”等表示转折的表达方式，接着陈述对方所忽略的前提等情况。",
